use core::sync::atomic::{AtomicU32 as A,Ordering as O};const AND:fn(&A,u32,O)->u32=A::fetch_and;const OR:fn(&A,u32,O)->u32=A::fetch_or;const XOR:fn(&A,u32,O)->u32=A::fetch_xor;const NAND:fn(&A,u32,O)->u32=A::fetch_nand;fn main(){let a=A::new(15);check(AND(&a,3,O::Relaxed)==15);check(OR(&a,8,O::Release)==3);check(XOR(&a,2,O::Acquire)==11);check(NAND(&a,1,O::AcqRel)==9);check(a.load(O::Relaxed)==4294967294);let f:unsafe fn(&A,u32,O)->u32=A::fetch_xor;unsafe{check(f(&a,4294967295,O::SeqCst)==4294967294);}check(A::fetch_or(&a,2,O::Relaxed)==1);check(a.load(O::Relaxed)==3);}
